bounded_host_request.command:
set -eu
test "$(git rev-parse HEAD)" = "4b06a39ebdb8a99d5544b27c8a52f33ad8e42440"
test -z "$(git status --porcelain --untracked-files=all)"
python3 -B - <<'PY'
import hashlib,subprocess,tarfile,io,stat,json
from pathlib import Path
p="server/tests/server-command-tool-runtime.test.cjs"
h=Path(p)
print("HOST_TEST_MODE="+oct(stat.S_IMODE(h.stat().st_mode)))
print("HOST_TEST_SHA256="+hashlib.sha256(h.read_bytes()).hexdigest())
cid=subprocess.check_output(["docker","compose","ps","--quiet","sandbox-runner"],text=True).strip()
try:
 raw=subprocess.check_output(["docker","cp",cid+":/app/"+p,"-"],stderr=subprocess.PIPE)
 with tarfile.open(fileobj=io.BytesIO(raw)) as t:
  members=[m for m in t.getmembers() if m.isfile()]
  assert len(members)==1
  m=members[0];f=t.extractfile(m);data=f.read()
  print("SANDBOX_TEST_MODE="+oct(m.mode))
  print("SANDBOX_TEST_SHA256="+hashlib.sha256(data).hexdigest())
  print("SANDBOX_TEST_BYTES_MATCH="+str(data==h.read_bytes()))
except subprocess.CalledProcessError as e:
 print("SANDBOX_TEST_COPY_FAILED="+str(e.returncode))
probe="const fs=require('node:fs');try{let s=fs.statSync('/app/"+p+"');console.log('SANDBOX_TEST_STAT_MODE='+((s.mode&511).toString(8)));fs.readFileSync('/app/"+p+"');console.log('SANDBOX_TEST_READABLE=YES')}catch(e){console.log('SANDBOX_TEST_READABLE=NO '+e.code)}"
subprocess.run(["docker","exec",cid,"node","-e",probe],check=True)
PY
